      display: flex; align-items: center; justify-content: space-between;
      padding: 22px 0; border-bottom: 1px solid var(--line);
    }
    .brand { display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: 18px; letter-spacing: -0.01em; }
    .mark {
      width: 26px; height: 26px; border-radius: 7px;
      background: var(--accent); display: inline-block; position: relative;
    }
    .mark::after {
      content: ""; position: absolute; inset: 7px 7px auto 7px; height: 3px;
      background: #fff; border-radius: 2px; box-shadow: 0 6px 0 #fff;
